/* CASEBENCH 1.0 designer — inserted inside the application closure by build.py. */
let caseResult=null,resultKey='',jobBusy=false,worker=null,workerURL=null,jobNumber=0,jobTimer=null,regenTimer=null,lastJobError='',faceOpen=false,faceName='lid',featureSelection=new Set(),couponResult=null;
const faceNames={lid:'Lid · outside',front:'Front wall',back:'Back wall',left:'Left wall',right:'Right wall',floor:'Base · outside floor','inside-floor':'Base · inside floor','inside-lid':'Lid · inside'};
const kindNames={'cutout':'Opening','pocket':'Pocket','text-raised':'Raised text','text-recessed':'Recessed text','vent':'Vent pattern','add':'Add material'};
const geometryKey=p=>p?M.geometryState(p):'';
const isCurrent=()=>!!caseResult&&resultKey===geometryKey(project)&&!jobBusy&&!lastJobError;
const allFindings=()=>[...(assembly?.findings||[]),...(isCurrent()?caseResult.findings.filter(f=>!['stale-trial','failed-trial'].includes(f.code)):[]),...geometryProofFindings()];
function makeField(name,label,value,type='number',extra=''){return `<label class="field"><span>${esc(label)}</span><input name="${esc(name)}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value??'')}" ${extra}></label>`;}
function makeCheck(name,label,value){return `<label class="check setting-check"><input type="checkbox" name="${esc(name)}" ${value?'checked':''}>${esc(label)}</label>`;}
function makeSelect(name,label,value,entries){return `<label class="field"><span>${esc(label)}</span><select name="${esc(name)}">${entries.map(e=>{let[k,v]=Array.isArray(e)?e:[e,e];return `<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`;}).join('')}</select></label>`;}
function formValues(form){const obj={};for(const el of form.elements){if(!el.name)continue;if(el.type==='checkbox')obj[el.name]=el.checked;else if(el.type==='number')obj[el.name]=el.value===''?null:el.valueAsNumber;else obj[el.name]=el.value;}return obj;}
function bindForm(id,callback){const form=$(id);if(form)form.onsubmit=e=>{e.preventDefault();try{callback(formValues(form));}catch(err){toast(err.message,true);}};}
function formFoot(label='Apply changes'){return `<button type="submit" class="primary full">${esc(label)}</button><p class="small muted">All dimensions in millimetres. The PCB is never scaled.</p>`;}
function heading(eyebrow,title,sub=''){return `<div class="inspector-heading"><button class="panel-close" data-close-panel="right" aria-label="Close inspector">✕</button><div class="eyebrow">${esc(eyebrow)}</div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div>`;}
function changeProject(fn,{regenerate=true}={}){if(!project)return;try{let draft=C.clone(project);fn(draft);draft=M.validate(draft);pushUndo();project=draft;assembly=M.effective(project);dirty();lastJobError='';renderAll(false);if(regenerate&&project.generated)scheduleGenerate();return true;}catch(e){toast('Change not applied: '+e.message,true);return false;}}
function scheduleGenerate(){clearTimeout(regenTimer);if(jobBusy)stopWorker(false);regenTimer=setTimeout(()=>generateCase(false),280);updateDesignerStatus();}
function stopWorker(user=true){clearTimeout(jobTimer);clearTimeout(regenTimer);jobNumber++;if(worker)worker.terminate();worker=null;if(workerURL)URL.revokeObjectURL(workerURL);workerURL=null;jobBusy=false;if(user){lastJobError='Generation cancelled. The previous mesh is shown only for reference.';toast('Generation cancelled. Project edits are kept; exports require regeneration.');}updateDesignerStatus();}
function makeWorker(){if(worker)return worker;workerURL=URL.createObjectURL(new Blob([window.CaseWorkerSource],{type:'text/javascript'}));worker=new Worker(workerURL);return worker;}
function runGeometry(kind,p,done){if(jobBusy)stopWorker(false);let n=++jobNumber;jobBusy=true;lastJobError='';lastFailedFeature=null;geometryStarted=performance.now();$('jobText').textContent=kind==='coupon'?'Building calibration coupons…':'Building enclosure solids…';updateDesignerStatus();try{const w=makeWorker();w.onmessage=e=>{const d=e.data;if(d.id!==jobNumber)return;if(d.type==='progress'){$('jobText').textContent=d.message;return;}clearTimeout(jobTimer);jobBusy=false;if(d.type==='error'){lastJobError=d.message;lastFailedFeature=d.featureId||null;updateDesignerStatus();toast('Generation stopped: '+d.message,true);return;}lastBuildDuration=performance.now()-geometryStarted;try{done(d.result);}catch(err){lastJobError='Result handling failed: '+err.message;toast(lastJobError,true);}updateDesignerStatus();};w.onerror=e=>{if(n!==jobNumber)return;lastJobError=e.message||'Geometry worker failed.';stopWorker(false);updateDesignerStatus();toast(lastJobError,true);};w.postMessage({id:n,kind,project:p});jobTimer=setTimeout(()=>{if(n!==jobNumber)return;stopWorker(false);lastJobError='Operation reached the 120-second limit. Reduce features, vent count or curve resolution, then regenerate.';updateDesignerStatus();toast(lastJobError,true);},120000);}catch(e){jobBusy=false;lastJobError='Geometry workers could not start: '+e.message;updateDesignerStatus();toast(lastJobError,true);}}
function renderGeometryResult(reset){
 const drafts=[...document.querySelectorAll('form[id]')].map(f=>({id:f.id,values:[...f.elements].filter(e=>e.name).map(e=>({name:e.name,value:e.value,checked:e.checked}))}));
 const focus=document.activeElement,focusId=focus?.form?.id,focusName=focus?.name,range=focus?.selectionStart==null?null:[focus.selectionStart,focus.selectionEnd];
 renderAll(reset);
 for(const draft of drafts){const form=$(draft.id);if(!form)continue;for(const v of draft.values){const el=[...form.elements].find(e=>e.name===v.name);if(el&&el.type!=='file'){el.value=v.value;if(el.type==='checkbox')el.checked=v.checked;}}}
 if(focusId&&focusName){const el=[...($(focusId)?.elements||[])].find(e=>e.name===focusName);if(el){el.focus({preventScroll:true});if(range&&el.setSelectionRange)try{el.setSelectionRange(...range);}catch(_){}}}
}
function generateCase(first=true){if(!project){toast('Open a PCB board first.');return;}clearTimeout(regenTimer);try{project=M.validate(project);if(first&&!project.generated){pushUndo();project.generated=true;project.view.scene='exploded';project.view.preset='iso';dirty();}const snapshot=C.clone(project),key=geometryKey(snapshot);runGeometry('build',snapshot,res=>{if(key!==geometryKey(project)){lastJobError='The project changed while generating. Regenerate before export.';return;}caseResult=res;caseResult.fingerprint=C.fingerprint(key);resultKey=key;viewer.caseResult=res;viewer.exportParts=null;renderGeometryResult(first);if(first)viewer.preset('iso');let errors=res.findings.filter(f=>f.severity==='error').length;toast(errors?'Enclosure generated with '+errors+' blocking finding(s). Open Review.':'Printable parts generated. Review dimensions and hardware before printing.',!!errors);});}catch(e){lastJobError=e.message;updateDesignerStatus();toast(e.message,true);}}
function updateDesignerStatus(){const ready=!!project,current=isCurrent();$('generateBtn').disabled=!ready||jobBusy;$('generateBtn').textContent=project?.generated?'Regenerate':'Generate enclosure';$('sceneSelect').disabled=!ready;$('faceEditBtn').disabled=!ready;$('sceneSelect').value=project?.view.scene||'board';$('jobNotice').hidden=!jobBusy&&!lastJobError&&(!caseResult||current);$('cancelJob').hidden=!jobBusy;$('jobNotice').classList.toggle('failed',!jobBusy);if(!jobBusy&&lastJobError)$('jobText').textContent=lastJobError+' Export is disabled until a current model passes checks.';else if(!jobBusy&&caseResult&&!current)$('jobText').textContent='Geometry is out of date. Showing the previous result; regenerate before export.';
 if(ready){const d=M.dimensions(project,assembly);$('caseDimensions').textContent=`Case body ${fmt(d.width)} × ${fmt(d.depth)} × ${fmt(d.top)} mm${project.settings.closure?' + fastening ears':''}`;$('metricMountDetail').textContent=`${M.mounts(project,assembly).filter(h=>h.enabled).length} proposed · ${Object.values(project.review.mounting).filter(v=>v==='use').length} confirmed`;$('findingCount').textContent=allFindings().filter(f=>f.severity!=='info').length;$('fitStatus').textContent=current?(allFindings().some(f=>f.severity==='error')?'Resolve blocking findings':'Model checked · physical fit untested'):'Review dimensions before printing';let scene=project.view.scene;$('viewStamp').innerHTML=`<strong>${scene==='board'?'BOARD + MECHANICAL ENVELOPES':scene==='export'?'EXPORTED MESH READ-BACK':scene==='section'?'UNCAPPED VISUAL CUTAWAY':esc(scene.toUpperCase())}</strong>${scene==='section'?'Inspection only · does not alter export':current?'Current geometry · physical fit untested':caseResult?'Previous geometry · export locked':'Generate to see your enclosure'}`;if(jobBusy)$('statusText').textContent='Geometry runs locally in a cancellable worker';}else{$('caseDimensions').textContent='';$('jobNotice').hidden=true;}
 document.querySelectorAll('[data-print-action]').forEach(b=>b.disabled=!current||allFindings().some(f=>f.severity==='error'));
}
function openDesignerTab(tab){setTab(tab);$('workspace').classList.remove('hide-left');if(innerWidth<=680)$('workspace').classList.add('hide-right');syncViewButtons();}
function setScene(scene){if(!project)return;if(scene!=='board'&&!caseResult){toast('Generate an enclosure to use this view.');return;}if(scene==='export'){inspectExports();return;}project.view.scene=scene;if(project.view.preset==='plan')project.view.preset='iso';faceOpen=false;renderAll(true);dirty();}
function renderCasePanel(host){const s=project.settings,d=M.dimensions(project,assembly);host.innerHTML=`<div class="designer-panel"><div class="callout"><strong>A base. A lid. Built around your board.</strong>Clearances include the visible assumed lead allowance. Review actual hardware before printing.</div><form id="caseForm"><h3>Envelope</h3>${makeCheck('autoSize','Size around the whole assembly',s.autoSize)}<div class="field-grid">${makeField('margin','Side clearance',s.margin)}${makeField('radius','Corner radius',s.radius)}</div><details ${s.autoSize?'':'open'}><summary>Exact interior size / offset</summary><div class="field-grid">${makeField('innerWidth','Interior width',s.innerWidth)}${makeField('innerDepth','Interior depth',s.innerDepth)}${makeField('offsetX','Center X offset',s.offsetX)}${makeField('offsetY','Center source-Y offset',s.offsetY)}</div><p class="small muted">Exact size applies when automatic sizing is off. Offsets always apply.</p></details><h3>Shell + height</h3><div class="field-grid">${makeField('wall','Wall',s.wall)}${makeField('floor','Floor',s.floor)}${makeField('roof','Lid roof',s.roof)}${makeField('topClearance','Above assembly',s.topClearance)}</div>${makeCheck('autoHeight','Automatic base height',s.autoHeight)}${makeField('height','Fixed base height (auto off)',s.height)}<h3>Board supports</h3>${makeCheck('autoSupport','Automatic support height',s.autoSupport)}<div class="field-grid">${makeField('bottomClearance','Below assembly',s.bottomClearance)}${makeField('leadAllowance','Assumed lead / solder projection',s.leadAllowance)}${makeField('supportHeight','Fixed support (auto off)',s.supportHeight)}${makeField('supportDiameter','Support outside diameter',s.supportDiameter)}${makeField('supportBore','PCB fastener bore',s.supportBore)}</div><p class="small muted">Supports stay centered on imported holes. Edit their intent in Mounting. No suitable holes? Add inside-floor material pads and verify retention.</p><h3>Lid joint</h3><div class="field-grid">${makeField('fit','Per-side joint clearance',s.fit)}${makeField('lipDepth','Skirt depth',s.lipDepth)}${makeField('lipWall','Skirt wall',s.lipWall)}</div>${makeCheck('closure','Independent screw-and-nut fastening ears',s.closure)}${formFoot('Apply enclosure settings')}</form><h3>Current dimensions</h3>${dl([['Shell body',`${fmt(d.width)} × ${fmt(d.depth)} × ${fmt(d.top)} mm`],['PCB underside height',`${fmt(d.boardZ)} mm`],['Standoff height',`${fmt(d.support)} mm`]])}<h3>Fastening ears</h3><div class="object-list compact">${M.closures(project,d).map((h,i)=>`<button class="object-item" data-inspect="${esc(h.id)}"><strong>Ear ${i+1}</strong><span>${h.enabled?'Enabled':'Disabled'} · X ${fmt(h.x)}</span></button>`).join('')}</div><h3>Reserved spaces</h3><p class="small muted">Add batteries, heatsinks, wire bundles, plug or tool-access envelopes. Internal spaces enlarge the automatic case; access spaces do not.</p><button id="addEnvelope" class="full">+ Reserve a space</button><div class="object-list compact">${project.envelopes.map(e=>`<button class="object-item" data-inspect="${esc(e.id)}"><strong>${esc(e.name)}</strong><span>${esc(e.role)}</span></button>`).join('')}</div></div>`;
 bindForm('caseForm',v=>changeProject(p=>Object.assign(p.settings,v)));$('addEnvelope').onclick=()=>{let e={id:M.uid('space'),name:'Reserved space',role:'internal',componentId:null,x:assembly.board.width/2,y:assembly.board.height/2,z:assembly.board.thickness,width:10,depth:10,height:10};changeProject(p=>p.envelopes.push(e));selectObject(e.id);};bindInspects(host);}
function bindInspects(host){host.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>selectObject(b.dataset.inspect));}
function renderFeaturePanel(host){host.innerHTML=`<div class="designer-panel"><div class="eyebrow">Customize a flat face</div>${makeSelect('newFace','Target face',faceName,Object.entries(faceNames))}<div class="tool-grid">${Object.entries(kindNames).map(([k,n])=>`<button data-new-feature="${k}"><strong>${k==='cutout'?'⊖':k==='text-raised'?'A↑':k==='text-recessed'?'A↓':k==='vent'?'▥':k==='add'?'⊕':'▱'}</strong>${esc(n)}</button>`).join('')}</div><p class="small muted">Choose a tool, then drag it on the face. All operations remain editable. Shift-click selects several features.</p><div class="inline-actions"><button id="editFaceNow">Open face editor</button><button id="copyFeature">Duplicate</button><button id="deleteFeature">Delete</button></div><details><summary>Arrange selected features</summary><div class="inline-actions"><button data-arrange="u">Align U</button><button data-arrange="v">Align V</button><button data-arrange="distribute">Distribute U</button></div><p class="small muted">Uses resolved face coordinates. Select features on the same face.</p></details><div class="object-list feature-list">${project.features.map(f=>`<button class="object-item ${featureSelection.has(f.id)?'active':''}" data-feature="${esc(f.id)}"><span class="object-icon">${f.enabled?'●':'○'}</span><span class="object-copy"><strong>${esc(f.name)}</strong><span>${esc(kindNames[f.kind])} · ${esc(faceNames[f.face])}</span></span>${f.componentId?'<span title="Component linked">↗</span>':''}</button>`).join('')||'<p class="empty-list">No custom features yet. A hole, a label, a little character.</p>'}</div></div>`;host.querySelector('[name=newFace]').onchange=e=>{faceName=e.target.value;drawFace();};host.querySelectorAll('[data-new-feature]').forEach(b=>b.onclick=()=>addFeature(b.dataset.newFeature));host.querySelectorAll('[data-feature]').forEach(b=>b.onclick=e=>{if(e.shiftKey){featureSelection.has(b.dataset.feature)?featureSelection.delete(b.dataset.feature):featureSelection.add(b.dataset.feature);}else featureSelection=new Set([b.dataset.feature]);selected=b.dataset.feature;faceName=project.features.find(f=>f.id===selected).face;faceOpen=true;renderAll();$('workspace').classList.remove('hide-right');});$('editFaceNow').onclick=()=>openFace(faceName);$('copyFeature').onclick=duplicateFeatures;$('deleteFeature').onclick=deleteFeatures;host.querySelectorAll('[data-arrange]').forEach(b=>b.onclick=()=>arrangeFeatures(b.dataset.arrange));}
function addFeature(kind,componentId=null){if(!project)return;let f=M.feature(kind,faceName,componentId);changeProject(p=>p.features.push(f));featureSelection=new Set([f.id]);selected=f.id;activeTab='features';faceOpen=true;renderAll();$('workspace').classList.remove('hide-right');if(innerWidth<=680)$('workspace').classList.add('hide-left');}
function duplicateFeatures(){if(!featureSelection.size)return;let next=[];changeProject(p=>{for(const f of p.features.filter(f=>featureSelection.has(f.id))){const n={...f,id:M.uid(),name:f.name+' copy',u:f.u+3,v:f.v-3};next.push(n);}p.features.push(...next);});featureSelection=new Set(next.map(f=>f.id));selected=next[0]?.id||'board';renderAll();}
function deleteFeatures(){if(!featureSelection.size)return;changeProject(p=>p.features=p.features.filter(f=>!featureSelection.has(f.id)));featureSelection.clear();selected='board';renderAll();}
function arrangeFeatures(action){let fs=project.features.filter(f=>featureSelection.has(f.id));if(fs.length<2){toast('Select at least two features with Shift-click.');return;}if(new Set(fs.map(f=>f.face)).size!==1){toast('Arrange features on the same face.',true);return;}let rr=fs.map(f=>M.resolvedFeature(f,project,assembly)).sort((a,b)=>a.u-b.u);changeProject(p=>{rr.forEach((r,i)=>{let f=p.features.find(f=>f.id===r.id);if(action==='distribute')M.shiftFeature(f,rr[0].u+(rr.at(-1).u-rr[0].u)*i/(rr.length-1)-r.u,0);else M.shiftFeature(f,action==='u'?rr[0].u-r.u:0,action==='v'?rr[0].v-r.v:0);});});}
function componentInspector(c){const o=project.overrides[c.id]||{},src=CaseCore.normalize((project.system?.boards.find(b=>b.id===c.boardId)?.source||project.source).text).components.find(x=>x.id===(c.originalId||c.id)),through=assembly.pads.some(p=>p.ownerId===c.id&&p.drill>0);$('inspector').innerHTML=heading('Mechanical review · '+c.side,c.ref,c.name)+`<div class="inspector-body"><div class="callout warn"><strong>${esc(c.geometryStatus||'Representative')} envelope</strong>These are physical space reservations, not manufacturer CAD. Review the actual installed part.</div><h3>Original PCB dimensions</h3>${src.body?dl([['Width × depth',`${fmt(src.body.width)} × ${fmt(src.body.depth)} mm`],['Body height',fmt(src.body.height)+' mm'],['Source placement',`X ${fmt(src.sourcePlacement.x)} / Y ${fmt(src.sourcePlacement.y)}`],['Board face',c.side]]):'<p>Body dimensions missing from source.</p>'}<form id="componentForm"><h3>Installed envelope</h3><div class="field-grid">${makeField('width','Width',o.width??c.body?.width)}${makeField('depth','Depth',o.depth??c.body?.depth)}${makeField('height','Installed body height',o.height??c.body?.height)}${makeField('lift','Gap above board face',o.lift||0)}${makeField('offsetX','Local X offset',o.offsetX||0)}${makeField('offsetY','Local Y offset',o.offsetY||0)}</div>${through?makeField('leadProjection','Opposite-face lead / solder projection',o.leadProjection??'')+'<p class="small muted">Blank = use the visible '+fmt(project.settings.leadAllowance)+' mm assumed allowance. Zero is an explicit user statement.</p>':''}${makeSelect('evidence','Dimension evidence',o.evidence||'representative',[['representative','Representative / not reviewed'],['user-entered','User-entered'],['datasheet-derived','Datasheet-derived'],['measured','Physically measured']])}<label class="field"><span>Evidence / assembly notes</span><textarea name="notes" rows="3">${esc(o.notes||'')}</textarea></label>${formFoot('Apply mechanical envelope')}</form><button id="resetEnvelope" class="full">Restore imported body</button><h3>Access</h3>${makeSelect('accessFace','Opening face',faceName,Object.entries(faceNames))}<button id="componentOpening" class="primary full">+ Opening linked to ${esc(c.ref)}</button><button id="componentSpace" class="full">+ Cable / tool access envelope</button><p class="small muted">You choose the opening direction. The app does not infer it from connector names. A linked opening follows this component and the board elevation.</p><button id="padDetails" class="full advance-only">Inspect transformed pad centers</button></div>`;bindForm('componentForm',v=>{if(v.leadProjection===null)delete v.leadProjection;changeProject(p=>p.overrides[c.id]=v);});$('resetEnvelope').onclick=()=>changeProject(p=>delete p.overrides[c.id]);$('componentOpening').onclick=()=>{faceName=$('inspector').querySelector('[name=accessFace]').value;addFeature('cutout',c.id);};$('componentSpace').onclick=()=>{let e={id:M.uid('space'),name:c.ref+' access',role:'cable',componentId:c.id,x:0,y:0,z:0,width:12,depth:20,height:12};changeProject(p=>p.envelopes.push(e));selectObject(e.id);};$('padDetails').onclick=()=>showPadTable(c);}
function mountInspector(h){let m=M.mounts(project,assembly).find(x=>x.id===h.id);$('inspector').innerHTML=heading('PCB support · exact imported position',objectTitle(h.id),'The hole center is never moved to resolve a collision.')+`<div class="inspector-body">${dl([['Center · source coordinates',`${fmt(h.sourceX)}, ${fmt(h.sourceY)} mm`],['PCB hole',`${fmt(h.diameter)} mm${h.slot?' · slot centerline '+fmt(h.slot)+' mm':''}`],['Support height',`${fmt(M.dimensions(project,assembly).support)} mm`]])}${h.ownerId||h.slot?'<div class="callout warn">'+(h.ownerId?'Component-linked hole: review the module, fastener and underside clearance before enabling a floor support.':'Slotted hole: choose its mounting purpose before enabling a centered support. The imported slot is preserved in full.')+' New board imports leave this support off until you choose it. Existing saved choices are preserved.</div>':''}<form id="supportForm">${makeSelect('intent','Mounting intent',project.review.mounting[h.id]||'candidate',[['candidate','Unreviewed mounting candidate'],['use','Confirmed: use for mounting'],['exclude','Do not use for mounting']])}${makeCheck('enabled','Generate support',m.enabled)}<div class="field-grid">${makeField('diameter','Outside diameter',m.outerDiameter)}${makeField('bore','Fastener bore',m.boreDiameter)}</div>${formFoot('Apply support')}</form><p class="small muted">Through-bolt and underside nut pocket. Review the nut dimensions in Print → Hardware, along with tool access and copper/washer clearance.</p></div>`;bindForm('supportForm',v=>changeProject(p=>{p.review.mounting[h.id]=v.intent;p.supports[h.id]={enabled:v.enabled&&v.intent!=='exclude',diameter:v.diameter,bore:v.bore};}));}
function closureInspector(h){$('inspector').innerHTML=heading('Independent lid fastener',h.id.replace('closure-','Ear '),'External screw ear, not a PCB mounting hole.')+`<div class="inspector-body"><form id="closureForm">${makeCheck('enabled','Enable this ear',h.enabled)}<div class="field-grid">${makeField('x','X · board coordinates',h.x)}${makeField('y','Y · source down',-h.y)}${makeField('diameter','Outside diameter',h.diameter)}${makeField('bore','Bolt bore',h.bore)}</div>${formFoot('Apply fastening ear')}</form><button id="resetClosure" class="full">Restore suggested position</button><p class="small muted">A detached ear is an error, not an extra printable part. Move it so it joins the shell and check PCB, connector and tool clearance.</p></div>`;bindForm('closureForm',v=>changeProject(p=>p.closures[h.id]={...v,y:-v.y}));$('resetClosure').onclick=()=>changeProject(p=>delete p.closures[h.id]);}
function spaceInspector(e){$('inspector').innerHTML=heading('Reserved mechanical envelope',e.name,'This shape is reference space, never included in STL or 3MF.')+`<div class="inspector-body"><form id="spaceForm">${makeField('name','Name',e.name,'text')}${makeSelect('role','Purpose',e.role,[['internal','Internal assembly space'],['cable','Cable / mating-plug access'],['tool','Tool / finger access']])}${makeSelect('componentId','Anchor',e.componentId||'',[['','PCB coordinate datum'],...assembly.components.map(c=>[c.id,c.ref+' · '+c.name])])}<div class="field-grid">${makeField('x','X center / offset',e.x)}${makeField('y','Source-Y center / offset',e.y)}${makeField('z','Bottom Z / offset',e.z)}${makeField('width','Width',e.width)}${makeField('depth','Depth',e.depth)}${makeField('height','Height',e.height)}</div><p class="small muted">With an anchor, XYZ offsets are relative to the body center in board axes. Without an anchor, Z is from the PCB underside. Internal spaces enlarge auto-size; cable/tool spaces only report obstructions.</p>${formFoot('Apply reserved space')}</form><button id="deleteSpace" class="full">Delete reserved space</button></div>`;bindForm('spaceForm',v=>changeProject(p=>Object.assign(p.envelopes.find(x=>x.id===e.id),v,{componentId:v.componentId||null})));$('deleteSpace').onclick=()=>{changeProject(p=>p.envelopes=p.envelopes.filter(x=>x.id!==e.id));selectObject('board');};}
function featureInspector(f){let rf=M.resolvedFeature(f,project,assembly),text=f.kind.startsWith('text');$('inspector').innerHTML=heading(kindNames[f.kind],f.name,faceNames[f.face]) + `<div class="inspector-body">${rf.unresolved?'<div class="callout warn"><strong>Missing component anchor</strong>Choose a replacement explicitly or detach the link. The opening has not been reassigned.</div>':''}<form id="featureForm">${makeField('name','Feature name',f.name,'text')}${makeCheck('enabled','Enabled (suppress without deleting)',f.enabled)}${makeSelect('face','Target face',f.face,Object.entries(faceNames))}${makeSelect('componentId','Anchor',f.componentId||'',[['','Face center'],...assembly.components.map(c=>[c.id,c.ref+' · '+c.name]),...(f.componentId&&!assembly.components.some(c=>c.id===f.componentId)?[[f.componentId,'Missing: '+f.componentId]]:[])])}<div class="field-grid">${makeField('u',f.componentId?'U offset from component':'U from face center',f.u)}${makeField('v',f.componentId?'V offset from component':'V from face center',f.v)}${makeField('rotation','Rotation · degrees',f.rotation)}${makeField('depth',f.kind==='add'||f.kind==='text-raised'?'Height / extrusion':'Pocket / recess depth',f.depth)}</div>${text?`${makeField('text','Drafting text · mixed-case',f.text,'text','maxlength="32"')}<div class="field-grid">${makeField('size','Letter height',f.size)}${makeField('spacing','Extra letter spacing',f.spacing)}</div>${makeSelect('alignment','Alignment at anchor',f.alignment,['left','center','right'])}<p class="small muted">Original block-drafting alphabet: letters, digits and common punctuation. Lowercase is rendered mixed-case. Counters remain holes; this is solid geometry, not a texture.</p>`:`${makeSelect('shape','Shape',f.shape,[['rounded','Rounded rectangle'],['rect','Rectangle'],['circle','Circle'],['slot','Slot / capsule']])}<div class="field-grid">${makeField('width',f.shape==='circle'?'Diameter':'Width',f.width)}${makeField('height','Height',f.height)}${makeField('radius','Corner radius',f.radius)}</div>${['cutout','vent'].includes(f.kind)?makeCheck('through','Cut through selected wall only',f.through):''}`}${f.kind==='vent'?`<h3>Pattern</h3><div class="field-grid">${makeField('columns','Columns',f.columns)}${makeField('rows','Rows',f.rows)}${makeField('pitchU','Column pitch',f.pitchU)}${makeField('pitchV','Row pitch',f.pitchV)}</div>`:''}${formFoot('Apply feature')}</form><div class="inline-actions"><button id="featureFaceBtn">Edit on face</button><button id="featureRotate">Rotate 15°</button><button id="featureDetach">Detach anchor</button><button id="featureUp">Earlier</button><button id="featureDown">Later</button><button id="featureDelete">Delete</button></div><p class="small muted">U runs right and V runs up when looking at the selected face from outside its material. Features rebuild in list order. A through-cut does not cut the opposite wall. Choose Both parts deliberately for seam-crossing cuts.</p></div>`;bindForm('featureForm',v=>{if(text)CaseMarkings.layout(v.text,v.size,v.spacing,v.alignment);changeProject(p=>Object.assign(p.features.find(x=>x.id===f.id),v,{componentId:v.componentId||null}));faceName=v.face;drawFace();});$('featureFaceBtn').onclick=()=>openFace(f.face);$('featureRotate').onclick=()=>changeProject(p=>p.features.find(x=>x.id===f.id).rotation+=15);$('featureDetach').onclick=()=>changeProject(p=>Object.assign(p.features.find(x=>x.id===f.id),{componentId:null,positioning:'center',u:rf.u,v:rf.v}));for(const[button,step]of[['featureUp',-1],['featureDown',1]])$(button).onclick=()=>changeProject(p=>{let i=p.features.findIndex(x=>x.id===f.id),j=i+step;if(j>=0&&j<p.features.length)[p.features[i],p.features[j]]=[p.features[j],p.features[i]];});$('featureDelete').onclick=()=>{featureSelection=new Set([f.id]);deleteFeatures();};}
function renderReviewPanel(host){let ff=allFindings();host.innerHTML=`<div class="designer-panel"><div class="callout ${ff.some(f=>f.severity==='error')?'warn':''}"><strong>${isCurrent()?'Current model checked':'Generate a current model to check enclosure fit'}</strong>Geometry, evidence and physical fit are different questions. Zero modeled collisions is not verified hardware fit.</div><label class="field"><span>Filter</span><select id="reviewFilter"><option value="review">Warnings + errors</option><option value="all">Everything</option><option value="error">Blocking errors</option></select></label><div id="reviewItems"></div></div>`;const draw=()=>{let filt=$('reviewFilter').value,show=ff.filter(f=>filt==='all'||filt==='review'&&f.severity!=='info'||filt===f.severity);$('reviewItems').innerHTML=show.map((f,i)=>`<article class="finding"><div class="finding-head"><span class="badge ${f.severity==='error'?'error':f.severity==='warning'?'warn':''}">${esc(f.severity)}</span><strong>${esc(f.confidence||'Review')}</strong></div><p>${esc(f.message)}</p><p class="evidence">${esc(f.evidence||'')}</p>${f.objects?.length?`<button data-inspect="${esc(f.objects[0])}">Inspect ${esc(objectTitle(f.objects[0]))}</button>`:''}</article>`).join('')||'<p class="empty-list">No findings in this filter. Physical fit remains untested.</p>';bindInspects($('reviewItems'));};$('reviewFilter').onchange=draw;draw();}
function hardwareTable(items){return `<table class="data-table"><thead><tr><th>Hardware</th><th>Qty</th><th>Candidate length</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.item)}</td><td>${i.quantity}</td><td>${i.suggestedLength?fmt(i.suggestedLength)+' mm':'—'}</td></tr>`).join('')}</tbody></table>`;}
function renderPrintPanel(host){const s=project.settings,ff=allFindings(),errors=ff.filter(f=>f.severity==='error');let audit=isCurrent()?caseResult.parts.map(p=>`<div class="audit-card"><strong>${esc(p.name)}</strong><span>${p.audit.valid?'Closed mesh':'Invalid mesh'} · ${p.audit.connectedComponents} solid</span><small>${p.audit.triangles.toLocaleString()} triangles · ${fmt(p.audit.volumeMm3/1000)} cm³</small></div>`).join(''):'';host.innerHTML=`<div class="designer-panel"><div class="callout ${errors.length?'warn':''}"><strong>${!isCurrent()?'Generate a current enclosure':errors.length?errors.length+' blocking finding(s)':'Ready for export review'}</strong>Print geometry is checked separately from dimensional evidence. Physical fit remains untested.</div>${audit}<div class="print-actions"><button class="primary" data-print-action="package">Download print package ZIP</button><button data-print-action="3mf">Export 3MF · all parts</button><div class="row"><button data-print-action="base">Base STL</button><button data-print-action="lid">Lid STL</button></div><button data-print-action="inspect">Inspect exported mesh</button><button id="openReviewPrint">Review findings</button></div><h3>Printer + fit profile</h3><form id="printForm">${makeField('printerName','Profile name',s.printerName,'text')}<div class="field-grid">${makeField('bedWidth','Bed width',s.bedWidth)}${makeField('bedDepth','Bed depth',s.bedDepth)}${makeField('fit','Per-side joint clearance',s.fit)}${makeField('minFeature','Minimum feature warning',s.minFeature)}${makeField('layerHeight','Reference layer height',s.layerHeight)}</div><h3>Screw-and-nut geometry</h3><p class="small muted">Nominal editable dimensions, not verified hardware specifications. Measure the selected parts.</p><div class="field-grid">${makeField('boltDiameter','Lid bolt bore',s.boltDiameter)}${makeField('supportBore','PCB bolt bore',s.supportBore)}${makeField('nutFlats','Nut across flats',s.nutFlats)}${makeField('nutDepth','Nut pocket depth',s.nutDepth)}${makeField('headDiameter','Lid head recess diameter',s.headDiameter)}${makeField('headDepth','Lid head recess depth',s.headDepth)}${makeField('closureDiameter','Default ear diameter',s.closureDiameter)}${makeField('curveSegments','Circular resolution',s.curveSegments)}</div>${formFoot('Apply printing / hardware settings')}</form><div class="inline-actions"><button id="savePrinter">Save local profile</button><button id="loadPrinter">Load local profile</button></div><h3>Test the fit first</h3><button id="couponBtn" class="full">Generate calibration coupon ZIP</button><p class="small muted">Three joint clearances, a mating plug and a four-size bolt-hole gauge. Dimensions and orientation instructions travel with the ZIP. Record the measured fit below.</p><form id="calibrationForm">${makeField('note','Calibration / material / orientation notes','','text')}<button class="full" type="submit">Record current fit settings</button></form>${project.calibrations.map(c=>`<p class="small muted">${esc(c.name)} · gap ${fmt(c.fit)} · ${esc(c.note)}</p>`).join('')}<h3>Assembly hardware</h3>${hardwareTable(isCurrent()?caseResult.hardware:CaseChecks.hardware(project,assembly,M.dimensions(project,assembly)))}<p class="small muted">STL uses millimetre-valued coordinates; 3MF explicitly encodes millimetres. Reference boards and components are excluded. Default base is floor-down, lid outside-face-down. Inspect support needs and orientation in a slicer. No G-code is generated.</p></div>`;bindForm('printForm',v=>changeProject(p=>Object.assign(p.settings,v)));host.querySelectorAll('[data-print-action]').forEach(b=>b.onclick=()=>b.dataset.printAction==='inspect'?inspectExports():askExport(b.dataset.printAction));$('openReviewPrint').onclick=()=>openDesignerTab('findings');$('savePrinter').onclick=()=>{try{const keys=['printerName','bedWidth','bedDepth','fit','minFeature','layerHeight','boltDiameter','supportBore','nutFlats','nutDepth','headDiameter','headDepth'];localStorage.setItem('casebench:printer-profile',JSON.stringify(Object.fromEntries(keys.map(k=>[k,s[k]]))));toast('Current printer / fit profile saved locally.');}catch(e){toast('Profile storage failed. Settings remain in project JSON.',true);}};$('loadPrinter').onclick=()=>{try{let txt=localStorage.getItem('casebench:printer-profile');if(!txt){toast('No saved printer profile.');return;}let profile=C.parse(txt);changeProject(p=>Object.assign(p.settings,profile));}catch(e){toast(e.message,true);}};$('couponBtn').disabled=jobBusy;$('couponBtn').onclick=()=>{const snap=C.clone(project);runGeometry('coupon',snap,r=>{couponResult=r;let pack=X.packageFiles(r,null);download('CASEBENCH-fit-coupons.zip',pack.zip,'application/zip');toast('Calibration coupons exported with measured-size instructions.');});};bindForm('calibrationForm',v=>changeProject(p=>{p.calibrations.push({name:p.settings.printerName,date:new Date().toISOString(),fit:p.settings.fit,boltDiameter:p.settings.boltDiameter,note:v.note});p.calibrations=p.calibrations.slice(-20);},{regenerate:false}));updateDesignerStatus();}
function checkExportReady(){if(!isCurrent())throw Error('Generate a current model before exporting.');let errs=allFindings().filter(f=>f.severity==='error');if(errs.length)throw Error('Resolve '+errs.length+' blocking finding(s) before print export.');}
function inspectExports(){try{checkExportReady();const mf=X.threeMF(caseResult.parts,project.title,project.settings.bedWidth),read=X.read3MF(mf);if(read.parts.some(p=>!p.audit.valid))throw Error('Export read-back failed.');viewer.exportParts=read.parts;project.view.scene='export';project.view.preset='iso';faceOpen=false;renderAll(true);dirty();toast('Showing actual serialized 3MF meshes read back from the export, not the editing model.');}catch(e){toast(e.message,true);}}
function askExport(kind){try{checkExportReady();let warnings=allFindings().filter(f=>f.severity==='warning'),layout=X.layout(caseResult.parts,project.settings.bedWidth),bedNote=layout.width>project.settings.bedWidth||layout.height>project.settings.bedDepth;modal('Review before printing',`<p><strong>${warnings.length} review warning(s).</strong> The modeled solids passed their current topology checks; actual dimensions, hardware and printed fit are not certified.</p>${bedNote?'<div class="callout warn"><strong>Combined layout exceeds the printer bed.</strong>Print the separate STL parts in separate jobs or rearrange them in your slicer.</div>':''}<p>Each part uses the orientation selected in Print. Raised lettering or added geometry may need supports. Confirm millimetre units, layer orientation and fastener dimensions in your slicer.</p><label class="check"><input id="exportAck" type="checkbox">I have reviewed the assumptions and will check the exported parts in my slicer.</label>`,[{label:'Cancel',action:closeModal},{label:'Export geometry',primary:true,action:()=>{try{checkExportReady();if(!$('exportAck').checked)return;let stem=filename(project.title);if(kind==='package'){let pack=X.packageFiles(caseResult,project,reportHTML(reportBody()));download(stem+'-print.zip',pack.zip,'application/zip');}else if(kind==='3mf'){let b=X.threeMF(caseResult.parts,project.title,project.settings.bedWidth);X.read3MF(b);download(stem+'.3mf',b,'model/3mf');}else{let part=caseResult.parts.find(p=>p.id===kind);if(!part)throw Error('This printable part is not present.');let b=S.stl(X.orient(part),part.name),a=S.audit(S.readSTL(b));if(!a.valid)throw Error('Serialized STL failed read-back.');download(stem+'-'+kind+'.stl',b,'model/stl');}closeModal();toast('Print geometry exported. Keep the project JSON for future edits.');}catch(e){toast(e.message,true);}}}]);let btn=$('dialogFoot').lastElementChild;btn.disabled=true;$('exportAck').onchange=()=>btn.disabled=!$('exportAck').checked;}catch(e){toast(e.message,true);}}
function openFace(face='lid'){if(!project)return;faceName=face;faceOpen=true;project.view.preset='iso';drawFace();openDesignerTab('features');$('faceEditor').hidden=false;}
function drawFace(){const pane=$('faceEditor');pane.hidden=!faceOpen||!project;if(pane.hidden)return;$('faceSelect').value=faceName;const d=M.dimensions(project,assembly),fr=M.frame(faceName,d,project.settings),w=fr.width,h=fr.height,pad=Math.max(w,h)*.075+2;let lines='',tick=5;for(let x=Math.ceil(-w/2/tick)*tick;x<w/2;x+=tick)lines+=`<line x1="${x}" y1="${-h/2}" x2="${x}" y2="${h/2}"/>`;for(let y=Math.ceil(-h/2/tick)*tick;y<h/2;y+=tick)lines+=`<line x1="${-w/2}" y1="${y}" x2="${w/2}" y2="${y}"/>`;
 let refs='';for(const c of assembly.components){if(!c.vertices.length)continue;let pts=c.vertices.map(v=>M.project(fr,[v.x,v.y,v.z+d.boardZ])),xs=pts.map(p=>p[0]),ys=pts.map(p=>-p[1]),x=Math.min(...xs),y=Math.min(...ys),rw=Math.max(...xs)-x,rh=Math.max(...ys)-y;refs+=`<rect x="${x}" y="${y}" width="${Math.max(.2,rw)}" height="${Math.max(.2,rh)}"/><text x="${x+rw/2}" y="${y+rh/2}" text-anchor="middle">${esc(c.ref)}</text>`;}
 let fs='';for(const f0 of project.features.concat(M.interfaceFeatures(project)).filter(f=>f.face===faceName)){let f=M.resolvedFeature(f0,project,assembly,d),content='',ext;try{ext=CaseFeatures.extents(f);if(f.kind.startsWith('text'))content=CaseMarkings.layout(f.text,f.size,f.spacing,f.alignment).runs.map(r=>`<rect x="${r.x}" y="${-r.y-r.height}" width="${r.width}" height="${r.height}"/>`).join('');else if(f.kind.startsWith('art-')){const groups=f.artGroups||[{rule:f.artRule||'evenodd',contours:f.contours}];content=groups.map(g=>`<path fill-rule="${g.rule==='evenodd'?'evenodd':'nonzero'}" d="${g.contours.map(c=>'M '+c.map(p=>(p[0]*f.width)+','+(-p[1]*f.height)).join(' L ')+' Z').join(' ')}"/>`).join('');}else{let poly=CaseFeatures.outline(f).map(p=>`${p[0]},${-p[1]}`).join(' ');if(f.kind==='vent'){for(let i=0;i<f.columns;i++)for(let j=0;j<f.rows;j++)content+=`<polygon points="${poly}" transform="translate(${(i-(f.columns-1)/2)*f.pitchU},${-(j-(f.rows-1)/2)*f.pitchV})"/>`;}else content=`<polygon points="${poly}"/>`;}}catch(_){ext={width:12,height:6,offsetX:0};content='<rect x="-6" y="-3" width="12" height="6"/>';}
 const picked=featureSelection.has(f.id)||f.groupId===selected;fs+=`<g data-face-feature="${esc(f.id)}" class="face-feature ${picked?'selected':''} ${['add','text-raised','art-raised'].includes(f.kind)?'additive':'subtractive'} ${f.enabled?'':'suppressed'}" transform="translate(${f.u},${-f.v}) rotate(${-f.rotation})"><title>${esc(f.name)}</title>${content}<rect class="feature-hit" x="${ext.offsetX-ext.width/2}" y="${-ext.height/2}" width="${Math.max(ext.width,.5)}" height="${ext.height}"/>${picked&&!f.groupId&&!f.kind.startsWith('text')&&f.kind!=='vent'?`<rect data-resize="${esc(f.id)}" class="resize-handle" x="${f.width/2-1}" y="${-f.height/2-1}" width="2" height="2"/>`:''}</g>`;}
 let dims='';const pick=project.features.find(f=>f.id===selected&&f.face===faceName)||M.interfaceFeatures(project).find(f=>f.groupId===selected&&f.face===faceName);if(pick){try{const resolved=M.resolvedFeature(pick,project,assembly,d),b=M.featureBounds(pick),left=resolved.u+b.minU,top=resolved.v+b.maxV,xc=resolved.u+(b.minU+b.maxU)/2,yc=resolved.v+(b.minV+b.maxV)/2;dims=`<g class="selected-dimensions" pointer-events="none"><line x1="${-w/2}" y1="${-yc}" x2="${left}" y2="${-yc}"/><line x1="${xc}" y1="${-h/2}" x2="${xc}" y2="${-top}"/><text x="${(-w/2+left)/2}" y="${-yc-1}" text-anchor="middle">${fmt(left+w/2)} mm</text><text x="${xc+1}" y="${(-h/2-top)/2}">${fmt(h/2-top)} mm</text></g>`;}catch(_){}}
 $('faceCanvas').innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${-w/2-pad} ${-h/2-pad} ${w+pad*2} ${h+pad*2}" role="img" aria-label="${esc(faceNames[faceName])} drafting view"><rect class="face-outline" x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="${['lid','floor','inside-lid','inside-floor'].includes(faceName)?Math.max(0,d.radius):0}"/><g class="face-grid">${lines}</g><g class="face-references">${refs}</g><line class="face-axis" x1="${-w/2}" x2="${w/2}" y1="0" y2="0"/><line class="face-axis" y1="${-h/2}" y2="${h/2}" x1="0" x2="0"/>${fs}${dims}<text class="face-dimension" x="0" y="${h/2+pad*.65}" text-anchor="middle">${fmt(w)} mm · U → / V ↑</text></svg>`;
 $('faceCaption').textContent=faceNames[faceName]+' · drafting positions / projected reference envelopes. Inspect the regenerated 3D solid for actual cuts. Drag to move; square handle resizes.';bindFaceDrag();}
function bindFaceDrag(){
 const svg=$('faceCanvas').querySelector('svg');if(!svg)return;
 const point=e=>{let p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const a=p.matrixTransform(svg.getScreenCTM().inverse());return{u:a.x,v:-a.y};};let drag=null;
 svg.onpointerdown=e=>{const group=e.target.closest('[data-face-feature]');if(!group)return;const id=group.dataset.faceFeature,f=project.features.find(f=>f.id===id)||M.interfaceFeatures(project).find(f=>f.id===id);if(!f)return;const parent=project.workflow.interfaces.find(g=>g.id===f.groupId);selected=parent?parent.id:id;
  if(parent)featureSelection=new Set();else if(e.shiftKey)featureSelection.has(id)?featureSelection.delete(id):featureSelection.add(id);else if(!featureSelection.has(id))featureSelection=new Set([id]);
  renderInspector();renderDrawer();revealInspector();svg.setPointerCapture(e.pointerId);drag={start:point(e),f:{...f},parentId:parent?.id,resize:!parent&&!!e.target.closest('[data-resize]'),group,id,dx:0,dy:0};e.preventDefault();};
 svg.onpointermove=e=>{if(!drag)return;const pt=point(e),snap=Number($('faceSnap').value),q=x=>snap?Math.round(x/snap)*snap:x,dx=q(pt.u-drag.start.u),dy=q(pt.v-drag.start.v);drag.dx=dx;drag.dy=dy;const f=M.resolvedFeature(drag.f,project,assembly);
  if(drag.resize){const angle=-drag.f.rotation*Math.PI/180,x=dx*Math.cos(angle)-dy*Math.sin(angle),y=dx*Math.sin(angle)+dy*Math.cos(angle);drag.width=Math.max(.2,q(drag.f.width+2*x));drag.height=drag.f.shape==='circle'?drag.width:Math.max(.2,q(drag.f.height+2*y));$('faceCaption').textContent=`Resize preview ${fmt(drag.width)} × ${fmt(drag.height)} mm — release to apply`;}
  else{drag.group.setAttribute('transform',`translate(${f.u+dx},${-f.v-dy}) rotate(${-f.rotation})`);if(drag.parentId)$('faceCaption').textContent='Move interface group — all child geometry follows on release.';}};
 svg.onpointerup=()=>{if(!drag)return;const a=drag;drag=null;if(Math.abs(a.dx)+Math.abs(a.dy)<1e-5){drawFace();return;}changeProject(p=>{if(a.parentId){const g=p.workflow.interfaces.find(g=>g.id===a.parentId);g.u+=a.dx;g.v+=a.dy;}else if(a.resize){const f=p.features.find(f=>f.id===a.id);f.width=a.width;f.height=a.height;}else for(const f of p.features.filter(f=>featureSelection.has(f.id)&&f.face===faceName))M.shiftFeature(f,a.dx,a.dy);});};svg.onpointercancel=()=>{drag=null;drawFace();};
}
// Extend the proven import / recovery shell rather than replacing its source handling.
const oldRenderAll=renderAll,oldRenderDrawer=renderDrawer,oldRenderInspector=renderInspector,oldSelect=selectObject,oldInstall=installProject,oldUndo=undo,oldFresh=freshStart,oldStatus=updateStatus,oldObjectTitle=objectTitle,oldTab=setTab;
C.normalizedExport=p=>({...M.effective(p),app:'CASEBENCH-MECHANICAL',schema:3,version:M.VERSION,units:'mm',sourceSnapshot:p.source,mechanicalOverrides:p.overrides,reservedEnvelopes:p.envelopes,enclosureIntent:p.settings,enclosureSystem:p.system});
renderAll=function(reset=false){viewer.caseResult=caseResult;viewer.bedWidth=project?.settings.bedWidth;oldRenderAll(reset);drawFace();updateDesignerStatus();};
updateStatus=function(){oldStatus();updateDesignerStatus();};
objectTitle=function(id){return project?.features.find(f=>f.id===id)?.name||project?.envelopes.find(e=>e.id===id)?.name||(id==='base'?'Base':id==='lid'?'Lid':id.startsWith?.('closure-')?'Lid ear '+(Number(id.split('-')[1])+1):oldObjectTitle(id));};
renderDrawer=function(){if(!assembly||!['case','features','print','findings'].includes(activeTab)){oldRenderDrawer();if(assembly&&activeTab==='source'){const host=$('drawerContent'),button=document.createElement('button');button.id='updateRevisionBtn';button.className='full primary';button.textContent='Update PCB revision';button.onclick=()=>$('revisionInput').click();host.querySelector('.source-detail').prepend(button);$('normalizedBtn').onclick=()=>download(filename(project.title)+'-mechanical-review.json',JSON.stringify(C.normalizedExport(project),null,2));}return;}document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===activeTab);b.setAttribute('aria-pressed',b.dataset.tab===activeTab);});$('filterBar').hidden=true;const host=$('drawerContent');if(activeTab==='case')renderCasePanel(host);else if(activeTab==='features')renderFeaturePanel(host);else if(activeTab==='print')renderPrintPanel(host);else renderReviewPanel(host);};
renderInspector=function(){if(!assembly){oldRenderInspector();return;}let c=assembly.components.find(c=>c.id===selected),h=assembly.bores.find(h=>h.id===selected),f=project.features.find(f=>f.id===selected),e=project.envelopes.find(e=>e.id===selected),cl=M.closures(project).find(h=>h.id===selected);if(c)componentInspector(c);else if(h?.role==='mounting-candidate')mountInspector(h);else if(f)featureInspector(f);else if(e)spaceInspector(e);else if(cl)closureInspector(cl);else if(selected==='base'||selected==='lid'){$('inspector').innerHTML=heading('Generated part',selected==='base'?'Base':'Lid','Click a flat surface to edit it, or choose a face below.')+`<div class="inspector-body">${makeSelect('partFace','Face',selected==='base'?'front':'lid',Object.entries(faceNames).filter(([k])=>selected==='lid'?k.includes('lid'):!k.includes('lid')))}<button id="partEdit" class="primary full">Edit selected face</button></div>`;$('partEdit').onclick=()=>openFace($('inspector').querySelector('[name=partFace]').value);}else{oldRenderInspector();for(const el of $('inspector').querySelectorAll('h3'))if(el.textContent==='Known assembly envelope')el.textContent='Working clearance envelope';let box=$('inspector').querySelector('.callout');if(box)box.innerHTML='<strong>Imported geometry + explicit assumptions</strong>The original board is preserved. Installed dimensions, lead projections and reserved spaces can be reviewed without changing PCB. Generate a provisional enclosure, then resolve the findings before printing.';let btn=document.createElement('button');btn.className='primary full';btn.textContent='Design enclosure';btn.onclick=()=>openDesignerTab('case');$('inspector').querySelector('.inspector-body')?.prepend(btn);}};
selectObject=function(id){if(!project)return;if(id.startsWith('face:')){faceName=id.slice(5);selected=faceName.includes('lid')?'lid':'base';openFace(faceName);renderInspector();$('workspace').classList.remove('hide-right');return;}if(project.features.some(f=>f.id===id)){selected=id;featureSelection=new Set([id]);faceName=project.features.find(f=>f.id===id).face;faceOpen=true;renderAll();$('workspace').classList.remove('hide-right');return;}oldSelect(id);};
setTab=function(tab){oldTab(tab);$('workspace').classList.remove('hide-left');syncViewButtons();};
installProject=function(next){stopWorker(false);caseResult=null;resultKey='';viewer.caseResult=null;viewer.exportParts=null;featureSelection.clear();faceOpen=false;lastJobError='';oldInstall(next);if(project.generated)setTimeout(()=>generateCase(false),80);};
undo=function(redo=false){let before=geometryKey(project);oldUndo(redo);featureSelection=new Set([...featureSelection].filter(id=>project?.features.some(f=>f.id===id)));if(project?.generated&&before!==geometryKey(project))scheduleGenerate();};
freshStart=async function(){await oldFresh();if(!project){stopWorker(false);caseResult=null;resultKey='';viewer.caseResult=null;viewer.exportParts=null;faceOpen=false;featureSelection.clear();lastJobError='';renderAll();}};
reportBody=function(){if(!project)return'';const d=M.dimensions(project,assembly),current=isCurrent(),hardware=current?caseResult.hardware:CaseChecks.hardware(project,assembly,d);let image='';if(current&&project.view.scene!=='board'&&project.view.preset!=='plan'){try{let canvas=viewer.gl&&!viewer.lost?viewer.canvas:viewer.softCanvas;image=`<figure><img alt="Current inspection view; appearance may include exploded offsets or a cutaway" style="max-width:100%;max-height:420px;background:#edf0eb" src="${canvas.toDataURL('image/png')}"><figcaption>Current inspection view: ${esc(project.view.scene)}. Exploded offsets and cutaways are visual only.</figcaption></figure>`;}catch(_){}}
 return `<header><p class="eyebrow">GREEN SHOE GARAGE · FIELD INSTRUMENTS</p><h1>CIRCUITBENCH / Enclosure review</h1><p><strong>${esc(project.title)}</strong> · v${M.VERSION} · ${esc(new Date().toISOString())}</p><p><strong>${current?'Current generated geometry':'Geometry not generated or out of date'} · Physical fit untested.</strong> This is a model/evidence report, not a thermal, electrical, environmental or physical-fit certification.</p></header>${image}<div class="report-diagram">${V.planSVG(assembly,{theme:'light',top:true,bottom:true,pads:true,holes:true,labels:true})}</div><section><h2>Source + enclosure</h2>${dl([['Original source',project.source.filename],['Board ID',assembly.source.id],['Source fingerprint',project.source.fingerprint.value],['PCB',`${fmt(assembly.board.width)} × ${fmt(assembly.board.height)} × ${fmt(assembly.board.thickness)} mm`],['Shell body (excludes fastening ears)',`${fmt(d.width)} × ${fmt(d.depth)} × ${fmt(d.top)} mm`],['Wall / floor / roof',`${fmt(project.settings.wall)} / ${fmt(project.settings.floor)} / ${fmt(project.settings.roof)} mm`],['PCB underside above print datum',fmt(d.boardZ)+' mm'],['Assumed lead projection',fmt(project.settings.leadAllowance)+' mm unless individually overridden'],['Joint per-side gap',fmt(project.settings.fit)+' mm'],['Printer profile',project.settings.printerName]])}</section><section><h2>Printed parts + hardware</h2>${current?caseResult.parts.map(p=>`<p><strong>${esc(p.name)}:</strong> ${p.audit.valid?'closed topology':'FAILED'}; ${p.audit.connectedComponents} connected solid(s); ${p.audit.triangles} triangles; bounds ${p.audit.size.map(fmt).join(' × ')} mm; volume ${fmt(p.audit.volumeMm3/1000)} cm³.</p>`).join(''):'<p>No current part audit is available.</p>'}${hardwareTable(hardware)}<p>Candidate fastener lengths and all recess dimensions require actual hardware review. Base floor faces the print bed; lid outside face faces the print bed. Raised lettering may require reorientation or supports. STL coordinates are millimetre-valued; 3MF explicitly declares millimetres.</p></section><section><h2>Mechanical evidence</h2><table><thead><tr><th>Part</th><th>Face</th><th>W × D × H mm</th><th>Evidence</th><th>Opposite projection</th></tr></thead><tbody>${assembly.components.map(c=>`<tr><td>${esc(c.ref)}</td><td>${c.side}</td><td>${c.body?[c.body.width,c.body.depth,c.body.height].map(fmt).join(' × '):'Unknown'}</td><td>${esc(c.geometryStatus)}</td><td>${project.overrides[c.id]?.leadProjection!==undefined?fmt(project.overrides[c.id].leadProjection)+' mm explicit':'Unresolved / default allowance'}</td></tr>`).join('')}</tbody></table>${Object.entries(project.overrides).map(([id,o])=>o.notes?`<p><strong>${esc(objectTitle(id))}:</strong> ${esc(o.notes)}</p>`:'').join('')}</section><section><h2>Features + reserved spaces</h2>${project.features.map(f=>`<p>${f.enabled?'Enabled':'Suppressed'}: <strong>${esc(f.name)}</strong> · ${esc(kindNames[f.kind])} · ${esc(faceNames[f.face])} · anchor ${esc(f.componentId?objectTitle(f.componentId):'face center')} · U/V ${fmt(f.u)} / ${fmt(f.v)} mm · rotation ${fmt(f.rotation)}°.</p>`).join('')||'<p>No custom features.</p>'}${project.envelopes.map(e=>`<p>${esc(e.name)} · ${esc(e.role)} · ${fmt(e.width)} × ${fmt(e.depth)} × ${fmt(e.height)} mm · reference only.</p>`).join('')}</section><section><h2>Findings</h2>${allFindings().map(f=>`<p><strong>${esc(f.severity.toUpperCase())} · ${esc(f.code)} · ${esc(f.confidence)}:</strong> ${esc(f.message)}<br>${esc(f.evidence||'')}</p>`).join('')}</section><section><h2>Assumptions, notes + revisions</h2>${assembly.sourceAssumptions.map(a=>`<p>${esc(a.status||'Open')}: ${esc(a.text)}</p>`).join('')}${assembly.sourceEvidence.map(a=>`<p>${esc(a.text||'')} ${esc(a.source||'')}</p>`).join('')}<p style="white-space:pre-wrap">${esc(project.review.notes)}</p>${Object.entries(project.review.objects).map(([id,n])=>`<p>${esc(objectTitle(id))}: ${esc(n)}</p>`).join('')}${project.revisions.map(r=>`<p>${esc(r.date)} · ${esc(r.from)} → ${esc(r.to)} · ${r.changes.length} change(s)</p>`).join('')}${project.calibrations.map(c=>`<p>${esc(c.date)} · ${esc(c.name)} · per-side fit ${fmt(c.fit)} mm · ${esc(c.note)}</p>`).join('')}</section>`;};
showReport=function(){if(!project)return;let body=reportBody();modal('Enclosure review report',body,[{label:'Download HTML report',action:()=>download(filename(project.title)+'-enclosure-review.html',reportHTML(body),'text/html')},{label:'Print / Save PDF',primary:true,action:()=>{$('printArea').innerHTML=body;window.print();}},{label:'Close',action:closeModal}]);};
showHelp=function(){modal('CASEBENCH v1.0 · From board to enclosure',`<p>Open native PCB JSON (schemas 1–5) or a project ZIP. Review component dimensions and mounting intent. Choose <strong>Generate enclosure</strong>, then select a flat face to add openings, pockets, raised or recessed lettering, vents and material.</p><h3>Inspect before you print</h3><p>Assembled, exploded, transparent, uncapped section and print-layout views use actual generated meshes. The export read-back view parses the generated 3MF. Colored components and reserved spaces are references, not printed geometry. Review warnings, calibrate the fit, then export separate STL files or a 3MF/ZIP.</p><h3>Editing</h3><p>Drag to orbit; Shift-drag to pan; wheel to zoom. A flat face opens its 2D editing canvas. Drag a feature to move it; use the square handle to resize. Dimensions, rotations and component anchors remain editable in the inspector. Shift-click features to arrange several. Undo/redo covers design changes. Easy and Advanced use the same complete project.</p><h3>Dimensions are evidence, not promises</h3><p>Imported bodies are representative. Mechanical overrides never rewrite the PCB source. A visible assumed lead/solder projection is used until you enter an explicit value. Hardware sizes and candidate bolt lengths are editable conveniences. Access-envelope and insertion checks are conservative; the app does not solve a full articulated assembly path.</p><h3>Release boundaries</h3><p>One PCB, one rounded-rectangular base and screw-fastened lid. Planar editing; block-drafting mixed-case lettering. Local Manifold solid operations; edge/topology and volume checks are not a general industrial CAD certification. No STEP, general mesh import, slicing, G-code, thermal simulation, weatherproofing or electrical-safety claim. Large/degenerate feature combinations can fail with an explicit error. The last good mesh remains visible, but stale exports are locked.</p><h3>Local and portable</h3><p>All code, lettering geometry and worker source are embedded. No account, telemetry, CDN or external geometry service. Open the standalone HTML directly, or host index.html as a static page. Browser storage can be unavailable or cleared: download project JSON. The previous autosave is retained when storage permits.</p><div class="inline-actions"><button id="offlineBtn">Enable hosted offline cache</button><button id="recoveryOpenBtn">Restore previous autosave</button><button id="clearSampleBtn">Clear sample data</button></div><h3>Revisions</h3><p>Source → Update PCB revision previews changes before replacing the embedded source. Stable IDs keep feature relationships; removed anchors remain visibly unresolved. No reference-name guessing or silent reassignment.</p><h3>Keyboard + files</h3><p>Ctrl/Cmd-S saves project JSON; Ctrl/Cmd-O opens a file; Ctrl/Cmd-Z undoes; Shift adds redo. Escape closes the face editor or cancels pointer interaction. ZIP: Store or raw DEFLATE, 16 MiB archive, 8 MiB per JSON; no encrypted or ZIP64 imports. Old CASEBENCH v0.1 project JSON migrates on open.</p>`,[{label:'Close',action:closeModal}]);$('offlineBtn').disabled=location.protocol==='file:'||!('serviceWorker' in navigator);$('offlineBtn').onclick=async()=>{try{await navigator.serviceWorker.register('./sw.js',{scope:'./'});toast('Hosted offline cache registration requested. Reload after the worker installs.');}catch(e){toast('Offline cache unavailable; the standalone HTML remains self-contained.',true);}};$('recoveryOpenBtn').onclick=()=>restoreSaved(true);$('clearSampleBtn').onclick=async()=>{closeModal();if(project?.source.isExample)await freshStart();else toast('No active sample. Your project was kept.');};};
// DOM wiring (ordinary application actions remain bound after this fragment).
$('generateBtn').onclick=()=>generateCase(true);$('cancelJob').onclick=()=>stopWorker(true);$('sceneSelect').onchange=e=>setScene(e.target.value);$('faceEditBtn').onclick=()=>openFace(faceName);$('closeFace').onclick=()=>{faceOpen=false;drawFace();};$('faceSelect').innerHTML=Object.entries(faceNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('faceSelect').onchange=e=>{faceName=e.target.value;drawFace();renderDrawer();};
if(!$('revisionInput')){let el=document.createElement('input');el.id='revisionInput';el.type='file';el.accept='.json,application/json';el.hidden=true;document.body.append(el);}
$('revisionInput').onchange=async e=>{let file=e.target.files[0];e.target.value='';if(!file||!project)return;try{if(file.size>CaseCore.LIMITS.jsonBytes)throw Error('Revision JSON exceeds 8 MiB.');let text=await file.text(),preview=M.revisionPreview(project,text);modal('Review the incoming board revision',`<p><strong>${esc(file.name)}</strong></p>${preview.differentBoard?'<div class="callout warn"><strong>Different board identity</strong>This may be a different project rather than a revision. No feature is matched by name.</div>':''}<p>${preview.changes.length} source change(s); ${preview.missingLinks.length} missing feature anchor(s); ${preview.orphanOverrides.length} orphan override(s).</p><h3>Mechanical consequences</h3>${(preview.mechanical||[]).map(c=>`<p><strong>${esc(c.ref)}</strong>: ${esc(c.changed.join(', '))}${c.overrideNeedsReview?' · retained override needs review':''}</p>`).join('')||'<p>No changed installed component geometry.</p>'}<div style="max-height:280px;overflow:auto">${preview.changes.map(c=>`<p>${esc(c.kind)} · ${esc(c.group)} · ${esc(c.id)}</p>`).join('')||'<p>No modeled source changes.</p>'}</div><p>Existing features and mechanical overrides remain. Removed anchors are not reassigned; they block export until resolved. The previous source becomes the baseline.</p>`,[{label:'Cancel',action:closeModal},{label:'Apply this revision',primary:true,action:()=>{changeProject(p=>Object.assign(p,M.applyRevision(p,text,file.name)));closeModal();toast('Board revision applied. Review changed geometry and unresolved anchors.');}}]);}catch(err){toast('Revision not applied: '+err.message,true);}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('dialog').open){faceOpen=false;drawFace();}if(e.key==='Delete'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&featureSelection.size){e.preventDefault();deleteFeatures();}});
